# frozen_string_literal: true

# Reference: srt (MIT) https://github.com/cpetersen/srt

require "srt"

require_relative "../../errors"

module Cvt
  module Adapters
    # Shared cue model and the three subtitle text formats. SRT parsing and
    # writing go through the `srt` gem; VTT and ASS use small built-in
    # parsers/writers. Cue times are integer milliseconds.
    module Subtitle
      FORMATS = %w[srt vtt ass].freeze
      Cue = Struct.new(:index, :start_ms, :end_ms, :text, keyword_init: true)

      ASS_HEADER = <<~ASS
        [Script Info]
        ; Generated by cvt
        ScriptType: v4.00+
        WrapStyle: 0
        PlayResX: 384
        PlayResY: 288

        [V4+ Styles]
        Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
        Style: Default,Arial,20,&H00FFFFFF,&H000000FF,&H00000000,&H00000000,0,0,0,0,100,100,0,0,1,2,0,2,10,10,10,1

        [Events]
        Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
      ASS

      module_function

      def convert(input, output, from, to, warnings = [])
        unless FORMATS.include?(from.to_s) && FORMATS.include?(to.to_s) && from.to_s != to.to_s
          raise Cvt::Errors.build(
            "unsupported_conversion",
            "native_subtitle cannot convert #{from} to #{to}",
            hint: "Use srt, vtt, or ass as subtitle formats."
          )
        end

        cues = read(input, from, warnings)
        validate!(cues)
        if from.to_s == "ass"
          warnings << {
            "code" => "style_loss",
            "message" => "ASS styling, effects, and positioning are not preserved."
          }
        end
        write(output, cues, to, warnings)
        warnings
      end

      def read(path, format, warnings = [])
        text = read_text(path)
        cues = case format.to_s
               when "srt" then parse_srt(text)
               when "vtt" then parse_vtt(text, warnings)
               when "ass" then parse_ass(text)
               else
                 raise invalid_error("Unsupported subtitle input format: #{format}")
               end

        if cues.empty?
          raise Cvt::Errors.build(
            "conversion_failed",
            "No subtitle cues found in the input",
            hint: "Check that the file contains SRT, VTT, or ASS cues."
          )
        end
        cues
      end

      def write(path, cues, format, warnings)
        content = case format.to_s
                  when "srt" then write_srt(cues)
                  when "vtt" then write_vtt(cues)
                  when "ass" then write_ass(cues)
                  else
                    raise invalid_error("Unsupported subtitle output format: #{format}")
                  end
        File.binwrite(path, content.encode(Encoding::UTF_8))
        warnings
      rescue SystemCallError => e
        raise invalid_error("Unable to write subtitle output: #{e.message}")
      end

      def read_text(path)
        raw = File.binread(path)
        text = raw.dup.force_encoding(Encoding::UTF_8)
        unless text.valid_encoding?
          raise Cvt::Errors.build(
            "conversion_failed",
            "Subtitle file is not valid UTF-8",
            hint: "Save the subtitle file as UTF-8 and retry."
          )
        end
        text.delete_prefix("\uFEFF").gsub("\r\n", "\n").gsub("\r", "\n")
      rescue SystemCallError => e
        raise invalid_error("Unable to read subtitle input: #{e.message}")
      end

      def parse_srt(text)
        document = SRT::File.parse(text)
        document.lines.map.with_index(1) do |line, position|
          if line.error || line.start_time.nil? || line.end_time.nil?
            raise invalid_error("SRT cue #{position} has an invalid timestamp", srt_hint)
          end

          Cue.new(
            index: position,
            start_ms: to_ms(line.start_time, position, srt_hint),
            end_ms: to_ms(line.end_time, position, srt_hint),
            text: line.text.join("\n")
          )
        end
      end

      def parse_vtt(text, warnings = [])
        cues = []
        settings_seen = false
        style_blocks_seen = false
        blocks = text.split(/\n{2,}/)

        blocks.each do |block|
          lines = block.split("\n")
          next if lines.empty?
          first = lines.first.strip
          next if first.start_with?("WEBVTT")
          next if first.start_with?("NOTE")
          if first.start_with?("STYLE", "REGION")
            style_blocks_seen = true
            next
          end

          timing_index = lines.index { |line| line.include?("-->") }
          if timing_index.nil?
            raise invalid_error("VTT block without a timestamp line", vtt_hint)
          end

          start_text, rest = lines[timing_index].split("-->", 2)
          end_text, *settings = rest.to_s.strip.split(/\s+/)
          settings_seen ||= !settings.empty?

          position = cues.size + 1
          start_ms = parse_vtt_time(start_text)
          end_ms = parse_vtt_time(end_text)
          if start_ms.nil? || end_ms.nil?
            raise invalid_error("VTT cue #{position} has an invalid timestamp", vtt_hint)
          end

          cues << Cue.new(
            index: position,
            start_ms: start_ms,
            end_ms: end_ms,
            text: lines[(timing_index + 1)..].to_a.join("\n")
          )
        end

        if settings_seen || style_blocks_seen
          warnings << {
            "code" => "style_loss",
            "message" => "VTT cue settings and style blocks are ignored and were not preserved."
          }
        end
        cues
      end

      def parse_ass(text)
        cues = []
        section = nil
        fields = nil

        text.each_line do |raw_line|
          line = raw_line.chomp
          if (match = line.match(/\A\[(.+)\]\z/))
            section = match[1].strip
            next
          end

          case section
          when /\AEvents\z/i
            if line.start_with?("Format:")
              fields = line.split(":", 2).last.split(",").map(&:strip)
            elsif line.start_with?("Dialogue:")
              if fields.nil?
                raise invalid_error("ASS Dialogue appears before its Format line", ass_hint)
              end
              cues << parse_ass_dialogue(line.sub(/\ADialogue:\s*/, ""), fields, cues.size + 1)
            end
          end
        end
        cues
      end

      def parse_ass_dialogue(body, fields, position)
        values = body.split(",", fields.size)
        start_index = fields.index { |name| name.casecmp?("start") }
        end_index = fields.index { |name| name.casecmp?("end") }
        text_index = fields.index { |name| name.casecmp?("text") }
        unless start_index && end_index && text_index &&
               values[start_index] && values[end_index] && values[text_index]
          raise invalid_error("ASS cue #{position} does not match the Events Format line", ass_hint)
        end

        start_ms = parse_ass_time(values[start_index])
        end_ms = parse_ass_time(values[end_index])
        if start_ms.nil? || end_ms.nil?
          raise invalid_error("ASS cue #{position} has an invalid timestamp", ass_hint)
        end

        Cue.new(
          index: position,
          start_ms: start_ms,
          end_ms: end_ms,
          text: plain_ass_text(values[text_index])
        )
      end

      def plain_ass_text(value)
        value.gsub(/\{[^}]*\}/, "")
             .gsub(/\\N/, "\n")
             .gsub(/\\n/, "\n")
             .gsub(/\\h/, " ")
      end

      def parse_vtt_time(value)
        match = /\A(?:(\d{1,3}):)?(\d{1,2}):(\d{2})(?:[.,](\d{1,3}))?\z/.match(value.to_s.strip)
        return nil unless match

        minutes = match[2].to_i
        seconds = match[3].to_i
        return nil if minutes >= 60 || seconds >= 60

        fraction = match[4]
        millis = case fraction&.length
                 when nil then 0
                 when 1 then fraction.to_i * 100
                 when 2 then fraction.to_i * 10
                 else fraction.to_i
                 end

        ((match[1].to_i * 60 + minutes) * 60 + seconds) * 1000 + millis
      end

      def parse_ass_time(value)
        match = /\A(\d+):(\d{2}):(\d{2})(?:\.(\d{1,3}))?\z/.match(value.to_s.strip)
        return nil unless match

        millis = case match[4]&.length
                 when nil then 0
                 when 1 then match[4].to_i * 100
                 when 2 then match[4].to_i * 10
                 else match[4].to_i
                 end
        (match[1].to_i * 3600 + match[2].to_i * 60 + match[3].to_i) * 1000 + millis
      end

      def to_ms(seconds, position, hint)
        value = (seconds.to_f * 1000).round
        if value.negative?
          raise invalid_error("SRT cue #{position} has a negative timestamp", hint)
        end
        value
      end

      def validate!(cues)
        previous_end = -1
        cues.each_with_index do |cue, position|
          number = cue.index || (position + 1)
          if cue.start_ms.negative? || cue.end_ms.negative?
            raise Cvt::Errors.build(
              "conversion_failed",
              "Subtitle cue #{number} has a negative timestamp",
              hint: "Set cue times to zero or later and retry."
            )
          end
          if cue.end_ms < cue.start_ms
            raise Cvt::Errors.build(
              "conversion_failed",
              "Subtitle cue #{number} ends before it starts",
              hint: "Ensure each cue end time is at or after its start time."
            )
          end
          if cue.start_ms < previous_end
            raise Cvt::Errors.build(
              "conversion_failed",
              "Subtitle cue #{number} overlaps the previous cue",
              hint: "Adjust overlapping timestamps so cues do not share time ranges."
            )
          end
          previous_end = cue.end_ms
        end
        cues
      end

      def write_srt(cues)
        document = SRT::File.new
        cues.each_with_index do |cue, position|
          document.lines << SRT::Line.new(
            sequence: position + 1,
            start_time: cue.start_ms / 1000.0,
            end_time: cue.end_ms / 1000.0,
            text: cue.text.split("\n")
          )
        end
        "#{document}\n"
      end

      def write_vtt(cues)
        body = cues.map do |cue|
          "#{vtt_time(cue.start_ms)} --> #{vtt_time(cue.end_ms)}\n#{cue.text}\n"
        end.join("\n")
        "WEBVTT\n\n#{body}"
      end

      def write_ass(cues)
        dialogues = cues.map do |cue|
          text = cue.text.gsub("\n", "\\N")
          "Dialogue: 0,#{ass_time(cue.start_ms)},#{ass_time(cue.end_ms)},Default,,0,0,0,,#{text}"
        end
        "#{ASS_HEADER}#{dialogues.join("\n")}\n"
      end

      def vtt_time(ms)
        hours = ms / 3_600_000
        minutes = (ms % 3_600_000) / 60_000
        seconds = (ms % 60_000) / 1000
        millis = ms % 1000
        format("%02d:%02d:%02d.%03d", hours, minutes, seconds, millis)
      end

      def ass_time(ms)
        centis = (ms.to_i + 5) / 10
        hours = centis / 360_000
        minutes = (centis % 360_000) / 6000
        seconds = (centis % 6000) / 100
        fraction = centis % 100
        format("%d:%02d:%02d.%02d", hours, minutes, seconds, fraction)
      end

      def invalid_error(message, hint = "")
        Cvt::Errors.build(
          "conversion_failed",
          message,
          hint: hint.empty? ? "Fix the cue timestamps and retry." : hint
        )
      end

      def srt_hint
        "Use SRT timestamps like 00:00:01,000 --> 00:00:03,000 and numeric cue indexes."
      end

      def vtt_hint
        "Use WEBVTT cues with timestamps like 00:00:01.000 --> 00:00:03.000."
      end

      def ass_hint
        "Use ASS timestamps like 0:00:01.00 and keep the Dialogue fields aligned with Format."
      end
    end
  end
end
